

        
        // --- FILE SWITCHER & MANAGEMENT SYSTEM ---
        let clientFileCache = {};

        function fetchFileList(currentFilename) {
            const selectEl = document.getElementById('activeFileSelect');
            if (!selectEl) return;

            if (window.location.protocol.startsWith('http')) {
                fetch('/api/list-files')
                    .then(res => res.json())
                    .then(data => {
                        if (data.success && data.files && data.files.length > 0) {
                            selectEl.innerHTML = data.files.map(f => {
                                const selected = (currentFilename && (f.filename === currentFilename || currentFilename.includes(f.filename))) ? 'selected' : '';
                                return `<option value="${f.filename}" ${selected}>📄 ${f.filename} (${f.location})</option>`;
                            }).join('');
                        }
                    })
                    .catch(() => {});
            } else {
                // Client-side local file list
                const filenames = Object.keys(clientFileCache);
                if (filenames.length > 0) {
                    selectEl.innerHTML = filenames.map(fn => {
                        const selected = (currentFilename && fn === currentFilename) ? 'selected' : '';
                        return `<option value="${fn}" ${selected}>📄 ${fn}</option>`;
                    }).join('');
                } else if (currentFilename) {
                    selectEl.innerHTML = `<option value="${currentFilename}" selected>📄 ${currentFilename}</option>`;
                }
            }
        }

        function switchActiveFile(filename) {
            if (!filename) return;

            if (window.location.protocol.startsWith('http')) {
                showStatus(`Loading file: "${filename}"...`, 'loading');
                fetch(`/api/load-file?filename=${encodeURIComponent(filename)}`)
                    .then(res => res.json())
                    .then(data => {
                        if (data.success) {
                            updateDashboard(data);
                            showStatus(`✅ Switched to file: "${filename}"`, 'success');
                            fetchFileList(filename);
                        } else {
                            showStatus(`Error loading file: ${data.error}`, 'error');
                        }
                    })
                    .catch(err => {
                        showStatus(`Error switching file: ${err.message}`, 'error');
                    });
            } else {
                if (clientFileCache[filename]) {
                    updateDashboard(clientFileCache[filename]);
                    showStatus(`✅ Switched to local file: "${filename}"`, 'success');
                    fetchFileList(filename);
                }
            }
        }

