        function cleanStationName(raw) {
            if (!raw) return 'Unknown';
            let s = raw.toString().trim();
            s = s.replace(/\s*\([^)]*\)$/, '').trim();
            s = s.replace(/\s*-\s*\?+.*$/, '').trim();
            s = s.replace(/\?+/g, '').trim();
            const baseCode = s.split('-')[0].trim();
            const thName = THAI_STATION_MAP[baseCode];
            if (thName && !s.includes(' - ')) {
                return `${s} - ${thName}`;
            }
            return s;
        }

