        let currentRawPage = 1;
        let currentRawLimit = 50;
        let filteredRawRows = [];

        function initRawDataFilters() {
            const stationSelect = document.getElementById('rawStationFilter');
            const lateTypeSelect = document.getElementById('rawLateTypeFilter');
            const routeTypeSelect = document.getElementById('rawRouteTypeFilter');

            if (!stationSelect || !lateTypeSelect) return;

            const stations = setToList(new Set(allRawRecords.map(r => cleanStationName(r.dest_station_name))));
            stations.sort();
            stationSelect.innerHTML = '<option value="">ทุกสถานี (All Stations)</option>' +
                stations.map(s => `<option value="${s}">${s}</option>`).join('');

            const lateTypes = setToList(new Set(allRawRecords.map(r => (r.soc_outbound_late_type_2nd_cutoff || 'Unknown').toString().trim().replace(/_/g, ' ').toUpperCase())));
            lateTypes.sort();
            lateTypeSelect.innerHTML = '<option value="">ทุกสาเหตุล่าช้า (All Late Types)</option>' +
                lateTypes.map(lt => `<option value="${lt}">${lt}</option>`).join('');

            const routeTypes = setToList(new Set(allRawRecords.map(r => (r.soc_outbound_route_type || 'Unknown').toString().trim().toUpperCase())));
            routeTypes.sort();
            if (routeTypeSelect) {
                routeTypeSelect.innerHTML = '<option value="">ทุกเส้นทาง (All Routes)</option>' +
                    routeTypes.map(rt => `<option value="${rt}">${rt}</option>`).join('');
            }
        }

        function setToList(setObj) {
            const arr = [];
            setObj.forEach(v => { if (v) arr.push(v); });
            return arr;
        }

        function filterAndRenderRawData() {
            const query = (document.getElementById('rawSearchInput').value || '').trim().toLowerCase();
            const selectedStation = document.getElementById('rawStationFilter').value;
            const selectedLateType = document.getElementById('rawLateTypeFilter').value;
            const selectedRouteType = document.getElementById('rawRouteTypeFilter') ? document.getElementById('rawRouteTypeFilter').value : '';

            filteredRawRows = allRawRecords.filter(r => {
                const st = cleanStationName(r.dest_station_name);
                const lt = (r.soc_outbound_late_type_2nd_cutoff || 'Unknown').toString().trim().replace(/_/g, ' ').toUpperCase();
                const rt = (r.soc_outbound_route_type || 'Unknown').toString().trim().toUpperCase();
                const shipId = (r.shipment_id || '').toString().toLowerCase();
                const toNum = (r.latest_to_number || '').toString().toLowerCase();

                const matchQuery = !query || shipId.includes(query) || toNum.includes(query) || st.toLowerCase().includes(query);
                const matchStation = !selectedStation || st === selectedStation || st.includes(selectedStation) || selectedStation.includes(st);
                const matchLateType = !selectedLateType || lt.includes(selectedLateType.toUpperCase()) || selectedLateType.toUpperCase().includes(lt);
                const matchRouteType = !selectedRouteType || rt.includes(selectedRouteType.toUpperCase()) || selectedRouteType.toUpperCase().includes(rt);

                return matchQuery && matchStation && matchLateType && matchRouteType;
            });

            const total = filteredRawRows.length;
            document.getElementById('modalRecordCount').innerText = `${total.toLocaleString()} records`;

            const totalPages = Math.max(1, Math.ceil(total / currentRawLimit));
            if (currentRawPage > totalPages) currentRawPage = 1;

            const startIdx = (currentRawPage - 1) * currentRawLimit;
            const pageRows = filteredRawRows.slice(startIdx, startIdx + currentRawLimit);

            const tbody = document.getElementById('rawTableBody');
            if (pageRows.length === 0) {
                tbody.innerHTML = '<tr><td colspan="11" style="text-align:center; padding:30px; color:#94a3b8;">ไม่พบข้อมูล Raw Data ที่ตรงกับเงื่อนไข</td></tr>';
            } else {
                tbody.innerHTML = pageRows.map((r, i) => {
                    const idx = startIdx + i + 1;
                    const st = cleanStationName(r.dest_station_name);
                    const lt = (r.soc_outbound_late_type_2nd_cutoff || '-').toString().trim().replace(/_/g, ' ').toUpperCase();
                    const delayMins = r.delay_mins !== undefined ? r.delay_mins : '-';
                    return `
                        <tr>
                            <td>${idx}</td>
                            <td><strong style="color:#1e293b;">${r.shipment_id || '-'}</strong></td>
                            <td><span class="station-name" style="font-size:11px;">${st}</span></td>
                            <td style="font-size:11px; color:#475569;">${r.first_soc_received_timestamp || '-'}</td>
                            <td style="font-size:11px; color:#475569;">${r.first_soc_outbound_timestamp || '-'}</td>
                            <td style="font-size:11px; color:#64748b;">${r.soc_outbound_based_received_2nd_cut_off_timestamp || '-'}</td>
                            <td><span style="font-weight:700; color:#e63946;">${delayMins}</span></td>
                            <td><span class="peak-tag" style="background:#fee2e2; color:#991b1b;">${lt}</span></td>
                            <td><span class="pct-text">${r.soc_outbound_route_type || '-'}</span></td>
                            <td style="font-size:11px;">${r.latest_to_number || '-'}</td>
                            <td style="font-size:11px;">${r.recieve_team || '-'}</td>
                        </tr>
                    `;
                }).join('');
            }

            const endIdx = Math.min(startIdx + currentRawLimit, total);
            document.getElementById('paginationInfo').innerText = total > 0 
                ? `กำลังแสดง ${startIdx + 1} - ${endIdx} จาก ${total.toLocaleString()} รายการ` 
                : 'ไม่มีรายการ';
            document.getElementById('pageIndicator').innerText = `หน้า ${currentRawPage} / ${totalPages}`;

            document.getElementById('btnPrevPage').disabled = (currentRawPage <= 1);
            document.getElementById('btnNextPage').disabled = (currentRawPage >= totalPages);
        }

        function changeRawPage(dir) {
            currentRawPage += dir;
            filterAndRenderRawData();
        }

        function openRawDataModal(stationName, lateTypeName, routeTypeName) {
            try {
                const modal = document.getElementById('rawDataModal');
                if (modal) modal.style.display = 'flex';

                initRawDataFilters();

                const stationSelect = document.getElementById('rawStationFilter');
                const lateTypeSelect = document.getElementById('rawLateTypeFilter');
                const routeTypeSelect = document.getElementById('rawRouteTypeFilter');

                if (stationSelect) {
                    if (stationName) {
                        const cleanTarget = cleanStationName(stationName);
                        const baseCode = stationName.split(' ')[0].split('-')[0].trim();
                        let targetOpt = '';
                        for (let opt of stationSelect.options) {
                            if (opt.value === cleanTarget || opt.value === stationName || opt.value.includes(stationName) || (baseCode && opt.value.startsWith(baseCode))) {
                                targetOpt = opt.value;
                                break;
                            }
                        }
                        stationSelect.value = targetOpt;
                    } else {
                        stationSelect.value = '';
                    }
                }

                if (lateTypeSelect) {
                    if (lateTypeName) {
                        let targetLt = '';
                        const searchLt = lateTypeName.trim().toUpperCase();
                        for (let opt of lateTypeSelect.options) {
                            if (opt.value.toUpperCase().includes(searchLt) || searchLt.includes(opt.value.toUpperCase())) {
                                targetLt = opt.value;
                                break;
                            }
                        }
                        lateTypeSelect.value = targetLt;
                    } else {
                        lateTypeSelect.value = '';
                    }
                }

                if (routeTypeSelect) {
                    if (routeTypeName) {
                        let targetRt = '';
                        const searchRt = routeTypeName.trim().toUpperCase();
                        for (let opt of routeTypeSelect.options) {
                            if (opt.value.toUpperCase().includes(searchRt) || searchRt.includes(opt.value.toUpperCase())) {
                                targetRt = opt.value;
                                break;
                            }
                        }
                        routeTypeSelect.value = targetRt;
                    } else {
                        routeTypeSelect.value = '';
                    }
                }

                currentRawPage = 1;
                filterAndRenderRawData();
            } catch (err) {
                console.error('Error opening Raw Data Modal:', err);
                const modal = document.getElementById('rawDataModal');
                if (modal) modal.style.display = 'flex';
            }
        }

        function closeRawDataModal() {
            document.getElementById('rawDataModal').style.display = 'none';
        }

        function exportRawCSV() {
            if (!filteredRawRows || filteredRawRows.length === 0) {
                alert('ไม่มีข้อมูลให้ดาวน์โหลด');
                return;
            }
            const headers = ['shipment_id', 'dest_station_name', 'first_soc_received_timestamp', 'first_soc_outbound_timestamp', 'soc_outbound_based_received_2nd_cut_off_timestamp', 'delay_mins', 'soc_outbound_late_type_2nd_cutoff', 'soc_outbound_route_type', 'latest_to_number', 'recieve_team'];
            let csvContent = 'data:text/csv;charset=utf-8,﻿' + headers.join(',') + '\n';

            filteredRawRows.forEach(r => {
                const row = headers.map(h => `"${(r[h] || '').toString().replace(/"/g, '""')}"`);
                csvContent += row.join(',') + '\n';
            });

            const encodedUri = encodeURI(csvContent);
            const link = document.createElement('a');
            link.setAttribute('href', encodedUri);
            link.setAttribute('download', `SOC_Raw_Data_Export_${new Date().toISOString().slice(0,10)}.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }

        // Listeners for Raw Data Modal inputs
        document.addEventListener('DOMContentLoaded', () => {
            const sInput = document.getElementById('rawSearchInput');
            const sStation = document.getElementById('rawStationFilter');
            const sLateType = document.getElementById('rawLateTypeFilter');
            const sLimit = document.getElementById('rawLimitSelect');

            if (sInput) sInput.addEventListener('input', () => { currentRawPage = 1; filterAndRenderRawData(); });
            if (sStation) sStation.addEventListener('change', () => { currentRawPage = 1; filterAndRenderRawData(); });
            if (sLateType) sLateType.addEventListener('change', () => { currentRawPage = 1; filterAndRenderRawData(); });
            const sRouteType = document.getElementById('rawRouteTypeFilter');
            if (sRouteType) sRouteType.addEventListener('change', () => { currentRawPage = 1; filterAndRenderRawData(); });
            if (sLimit) sLimit.addEventListener('change', (e) => { currentRawLimit = parseInt(e.target.value) || 50; currentRawPage = 1; filterAndRenderRawData(); });
        });

        // Station live search filter
        const searchInput = document.getElementById('stationSearch');
        if (searchInput) {
            searchInput.addEventListener('input', () => {
                const ranking = (currentDataset && currentDataset.ranking) ? currentDataset.ranking : [];
                const maxCount = (currentDataset && currentDataset.maxCount) ? currentDataset.maxCount : 1;
                const query = searchInput.value.trim().toUpperCase();
                
                const filtered = query ? ranking.filter(r => r.station.toUpperCase().includes(query)) : ranking;
                const tbody = document.getElementById('tableBody');
                
                if (filtered.length === 0) {
                    tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:25px; color:#94a3b8;">No matching stations found</td></tr>';
                    return;
                }
                
                tbody.innerHTML = filtered.map((item, index) => {
                    const rank = item.rank || (index + 1);
                    const barWidthPct = Math.min(100, Math.round((item.count / maxCount) * 100));
                    let rankClass = '';
                    if (rank === 1) rankClass = 'rank-1';
                    else if (rank === 2) rankClass = 'rank-2';
                    else if (rank === 3) rankClass = 'rank-3';

                    const stTitle = (item.station || '').replace(/'/g, "\\'");
                    return `
                        <tr class="clickable-row" onclick="openRawDataModal('${stTitle}')" style="cursor:pointer;" title="คลิกเพื่อดู Raw Data ของ ${item.station}">
                            <td><span class="rank-pill ${rankClass}">${rank}</span></td>
                            <td style="display:flex; align-items:center; justify-content:space-between; gap:8px;">
                                <span class="station-name">${item.station}</span>
                                <button type="button" class="btn-secondary" style="font-size:11px; padding:3px 8px; background:#eff6ff; color:#1d4ed8; border:1px solid #bfdbfe; border-radius:4px;" onclick="event.stopPropagation(); openRawDataModal('${stTitle}')">📋 Raw Data</button>
                            </td>
                            <td class="data-bar-cell">
                                <div class="data-bar-bg" style="width: ${barWidthPct}%;"></div>
                                <span class="data-bar-value">${item.count.toLocaleString()}</span>
                            </td>
                            <td><span class="pct-text">${item.pct}%</span></td>
                            <td><span class="peak-tag">${item.peakTime}</span></td>
                        </tr>
                    `;
                }).join('');
            });
        }

        // Initialize with default dataset
        window.addEventListener('DOMContentLoaded', () => {
            if (typeof INITIAL_DATA !== 'undefined') {
                updateDashboard(INITIAL_DATA);
            }
            if (window.location.protocol.startsWith('http')) {
                fetch('/api/current-data')
                    .then(res => res.json())
                    .then(data => {
                        if (data.success) {
                            updateDashboard(data);
                            showStatus(`Loaded dataset: ${data.filename}`, 'success');
                        }
                    })
                    .catch(() => {});
            }
        });
    